ALTER TABLE "tula"."organization_roles" ADD CONSTRAINT "organization_roles_permissions_shape" CHECK (cardinality("tula"."organization_roles"."permissions") <= 1000 and array_position("tula"."organization_roles"."permissions", null) is null and array_to_string("tula"."organization_roles"."permissions", ',') ~ '^((org:(sys:[a-z][a-z0-9_]{0,31}|(?!sys:)[a-z][a-z0-9_]{0,31}):[a-z][a-z0-9_]{0,31})(,org:(sys:[a-z][a-z0-9_]{0,31}|(?!sys:)[a-z][a-z0-9_]{0,31}):[a-z][a-z0-9_]{0,31})*)?$' and char_length(array_to_string("tula"."organization_roles"."permissions", ',')) - char_length(replace(array_to_string("tula"."organization_roles"."permissions", ','), ',', '')) = greatest(cardinality("tula"."organization_roles"."permissions") - 1, 0));